def to_ranges(nums: list[int]) -> str:
    """See SPEC.md."""
    s = sorted(set(nums))
    out = []
    i = 0
    while i < len(s):
        j = i
        while j + 1 < len(s) and s[j + 1] == s[j] + 1:
            j += 1
        if j - i + 1 >= 4:
            a, b = s[i], s[j]
            out.append(f"({a})-({b})" if a < 0 else f"{a}-{b}")
        else:
            out.extend(str(x) for x in s[i:j + 1])
        i = j + 1
    return ",".join(out)

